    out = [row[:] for row in grid]
    # The pattern consists of same-row marks separated by one background cell;
    # color the intervening cell with 2.
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == 0 and row[c - 1] != 0 and row[c + 1] != 0 and row[c - 1] == row[c + 1]:
